use sap_format::{read_sdb_file,sdb::native::{inspect_native_sdb,pack_model_to_native_sdb}};
fn main(){let original=read_sdb_file("/home/edo/REA/extracted/files/example_1_001.sdb").unwrap();let generated=pack_model_to_native_sdb(&sap_model::SapModel::default()).unwrap();for (label,file) in [("vendor",original),("generated",generated)]{let doc=inspect_native_sdb(&file).unwrap();let mut seen=std::collections::BTreeSet::new();for rec in doc.records(){if seen.insert(rec.class_id.clone()){if let Some(field)=rec.fields.iter().find(|f|f.name.as_deref()==Some("ClassVersion")){let v=i32::from_le_bytes(file.decompressed_stream[field.offset..field.offset+4].try_into().unwrap());println!("{label} {} ClassVersion={v}",rec.class_id);}}}}}
